//! Cross-language CSS fixtures generated by tools/css_goldens.py from the Python reference.
use dt_render::{card::Card, css::*};
use std::{collections::BTreeMap, time::Duration};
fn values() -> Vec<CssValues> {
    vec![
        BTreeMap::from([
            ("aa".into(), "#abcdef".into()),
            ("b0".into(), "0.25".into()),
            ("bs".into(), "0.5".into()),
        ]),
        BTreeMap::new(),
        BTreeMap::from([
            ("aa".into(), "#123456".into()),
            ("kk".into(), "1".into()),
            ("pr".into(), "0.75".into()),
        ]),
    ]
}
#[test]
fn python_goldens() {
    assert_eq!(static_css(800, 450), include_str!("golden/static.css"));
    assert_eq!(
        static_css(320, 180),
        include_str!("golden/static_small.css")
    );
    assert_eq!(
        keyframe_block("d42", &values()).unwrap(),
        include_str!("golden/keyframes.css")
    );
    assert_eq!(
        animate("d42", Duration::from_secs_f64(8.0 / 24.0), false).unwrap(),
        include_str!("golden/animate.css")
    );
    assert_eq!(
        animate("d42", Duration::from_secs(16), true).unwrap(),
        include_str!("golden/infinite.css")
    );
    assert_eq!(
        static_values(&values()[0]).unwrap(),
        include_str!("golden/values.css")
    );
    assert_eq!(idle_css(), include_str!("golden/idle.css"));
    let card = Card {
        image: "YWJj".into(),
        height: 285,
    };
    assert_eq!(card_height_css(285), include_str!("golden/height.css"));
    assert_eq!(card_image_css(&card), include_str!("golden/card.css"));
    assert_eq!(glow_css("YWJj"), include_str!("golden/glow.css"));
    assert_eq!(
        favicon_front_css('a').unwrap(),
        include_str!("golden/front_a.css")
    );
    assert_eq!(
        favicon_front_css('b').unwrap(),
        include_str!("golden/front_b.css")
    );
}
#[test]
fn rejects_injected_names_and_values() {
    for name in ["x}body{color:red}", "a\\b", "9name", ""] {
        assert!(keyframe_block(name, &values()).is_err());
    }
    for (key, value) in [
        ("unknown", "0"),
        ("aa", "red"),
        ("c0", "#000000;background:red"),
        ("b0", "NaN"),
        ("bs", "url(x)"),
        ("pr", "0\\0"),
    ] {
        assert!(static_values(&BTreeMap::from([(key.into(), value.into())])).is_err());
    }
    assert!(favicon_front_css('c').is_err());
    assert!(
        !card_image_css(&Card {
            image: "x\");color:red".into(),
            height: 200
        })
        .contains("color:red")
    );
    let css = idle_theme(&Card {
        image: "YWJj".into(),
        height: 285,
    })
    .unwrap();
    assert!(!css.contains('\\'));
    assert!(css.len() < 49500);
}
